// Regenerates golden data. Usage: node scripts/sim-golden.mjs [file] [--set base|legacy-buildings|wedge|array-max-volume]
// legacy-buildings must only ever be generated by code from before the wedge model (it pins the old behaviour).
import { mkdirSync, writeFileSync } from 'node:fs';
import { goldenFor } from '../test/golden-lib.js';
import { GOLDEN_SCENES, LEGACY_BUILDING_SCENES, WEDGE_SCENES, ARRAY_VOLUME_SCENES } from '../test/golden-scenes.js';

const args = process.argv.slice(2);
const setIdx = args.indexOf('--set');
const set = setIdx >= 0 ? args[setIdx + 1] : 'base';
if (set === 'realism') {
  const { realismGolden } = await import('../test/realism-fixture.js');
  writeFileSync(new URL('../test/golden/golden-realism.json', import.meta.url), JSON.stringify(realismGolden(), null, 2) + '\n');
  console.log('wrote test/golden/golden-realism.json (new opt-in physics only)');
  process.exit(0);
}
const SETS = { base: GOLDEN_SCENES, 'legacy-buildings': LEGACY_BUILDING_SCENES, wedge: WEDGE_SCENES };
if (set === 'analysis-0.4') {
  // Analysis only (schema 0.4), for every scene set; the signal goldens are not touched.
  const out = Object.fromEntries(Object.entries(SETS).map(([k, sc]) => [k, Object.fromEntries(Object.keys(sc).map((name) => [name, goldenFor(name, sc).analysis]))]));
  writeFileSync(new URL('../test/golden/golden-analysis-0.4.json', import.meta.url), JSON.stringify(out));
  console.log('wrote test/golden/golden-analysis-0.4.json');
  process.exit(0);
}
const scenes = set === 'array-max-volume' ? ARRAY_VOLUME_SCENES : SETS[set];
if (!scenes) throw new Error(`unknown set ${set}`);
const defaults = { base: 'test/golden/golden.json', 'legacy-buildings': 'test/golden/golden-legacy-buildings.json', wedge: 'test/golden/golden-wedge.json', 'array-max-volume': 'test/golden/golden-array-max-volume.json' };
const out = Object.fromEntries(Object.keys(scenes).map((name) => {
  const result = goldenFor(name, scenes);
  return [name, set === 'array-max-volume' ? { mics: result.mics } : result];
}));
const file = args.find((a, i) => !a.startsWith('--') && args[i - 1] !== '--set') || defaults[set];
mkdirSync(new URL('../test/golden/', import.meta.url), { recursive: true });
writeFileSync(new URL(`../${file}`, import.meta.url), JSON.stringify(out));
console.log(`wrote ${file}`);
